import{createHash,randomUUID}from"node:crypto";import{scheduleDisplayName}from"#runtime/schedules/record.js";import{ScheduleDispatcher}from"#channel/schedule.js";async function dispatchScheduledOccurrence(e){let t={...e.occurrence,displayName:scheduleDisplayName(e.occurrence.name)};let{provider:n}=e.definition;let providerContext=()=>createScheduleProviderContext({abortSignal:new AbortController().signal,application:e.payload.eve.application,bundle:()=>e.bundle,collection:e.collection,runtime:()=>e.runtime,definition:e.definition,namespace:e.namespace,operationId:randomUUID(),scope:e.payload.envelope.scope});let r=await new ScheduleDispatcher({runtime:e.runtime,channels:e.bundle.graph.root.channels}).triggerCollection({collectionId:e.collection,definition:e.definition,occurrence:t,payload:e.payload,schedule:{async disable(){await n.disable(providerContext(),t.name)},async delete(){await n.delete(providerContext(),t.name)}},verifyDelivery:e.verifyDelivery});await e.definition.events?.[`occurrence.dispatched`]?.({collection:e.collection,executionId:e.occurrence.executionId,name:t.name,occurrence:t,scheduledAt:e.occurrence.scheduledAt,scheduleId:e.occurrence.scheduleId,sessionIds:r.sessions.map(e=>e.sessionId),schedule:e.payload.envelope,type:`occurrence.dispatched`})}function createScheduleProviderContext(e){return{abortSignal:e.abortSignal,collection:e.collection,namespace:e.namespace??deriveScheduleNamespace(e.application,e.collection,e.scope),operationId:e.operationId,target:{key:e.application,deliver:async({payload:t,occurrence:n})=>{await dispatchScheduledOccurrence({bundle:e.bundle(),collection:e.collection,runtime:e.runtime(),definition:e.definition,occurrence:{...n,collection:e.collection},payload:t})}}}}function deriveScheduleNamespace(e,t,n){if(e.trim().length===0)throw Error(`Schedule application must not be empty.`);return`eve-${createHash(`sha256`).update(JSON.stringify([`eve-schedule-namespace-v2`,e,t,n])).digest(`base64url`)}`}export{createScheduleProviderContext,dispatchScheduledOccurrence};